1676	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1677	  const signal = resolveRunSignal(options);
1678	  const nodes = validateWorkflow(workflow);
1679	  verifyOperations(nodes, operations);
1680	
1681	  const state = createRunState(nodes, workflow, input);
1682	
1683	  // A signal that is already aborted stops the run before the first node —
1684	  // but only after the definition and the operation registrations above have
1685	  // been checked. Nothing executes and nothing is compensated.
1686	  if (signal && signal.aborted) {
1687	    return withCompensation(cancelledResult(state), state, operations);
1688	  }
1689	
1690	  for (;;) {
1691	    // Once the signal fires, no new regular node runs and no new business
1692	    // action attempt starts; the run ends cancelled with whatever state it
1693	    // reached, even if an end node was already visited on another branch.
1694	    if (signal && signal.aborted) {
1695	      return withCompensation(cancelledResult(state), state, operations);
1696	    }
1697	
1698	    const step = advanceSchedule(state);
1699	
1700	    if (step.kind === 'blocked') {
1701	      // Unmet dependencies end the run; successful compensable actions are
1702	      // rolled back even though an end node may already have been reached.
1703	      return withCompensation({
1704	        status: 'blocked', context: state.context, trace: state.trace,
1705	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1706	      }, state, operations);
1707	    }
1708	    if (step.kind === 'completed') {
1709	      // A completed run never invokes compensation.
1710	      return {
1711	        status: 'completed', result: state.endResult, context: state.context,
1712	        trace: state.trace, actionAttempts: state.actionAttempts,
1713	        compensationStatus: 'not_needed', compensationAttempts: [],
1714	      };
1715	    }
1716	    if (step.kind === 'end') continue;
1717	
1718	    const ready = step.node;
1719	    if (ready.type === 'action') {
1720	      const binding = actionBindings.get(ready);
1721	      if (binding.name !== null) {
1722	        // Nodes execute one at a time in declaration order; awaiting here
1723	        // never lets another node jump ahead.
1724	        const actionResult = await runBusinessAction(
1725	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1726	        if (!actionResult.ok) {
1727	          if (actionResult.cancelled) {
1728	            // Cancelled while the action was in flight or waiting to retry:
1729	            // the attempt records produced so far stay as they are.
1730	            return withCompensation(cancelledResult(state), state, operations);
1731	          }
1732	          // Retries are exhausted: stop immediately with prior input/output
1733	          // preserved, no output for this node and no successors activated —
1734	          // even if an end node was already reached — then compensate every
1735	          // earlier successful action that asked for it.
1736	          return withCompensation({
1737	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1738	            error: actionResult.error, context: state.context, trace: state.trace,
1739	            actionAttempts: state.actionAttempts,
1740	          }, state, operations);
1741	        }
1742	        // Capture the compensation snapshots from the state before the new
1743	        // output key lands: the action's own return value is handed to the
1744	        // compensation separately as its third argument.
1745	        const compensationSnapshot = binding.compensation === null ? null : {
1746	          input: structuredClone(state.context.input),
1747	          output: structuredClone(state.context.output),
1748	          result: structuredClone(actionResult.value),
1749	        };
1750	        setNodeOutput(state.context.output, ready.id, actionResult.value);
1751	        if (compensationSnapshot) {
1752	          // Each node completes at most once, so retried-then-successful
1753	          // actions and shared join nodes are scheduled for compensation
1754	          // exactly once.
1755	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
1756	        }
1757	        for (const target of successorTargets.get(ready)) state.activated.add(target);
1758	        state.completed.add(ready.id);
1759	        continue;
1760	      }
1761	    }
1762	
1763	    const early = applyRegularNode(ready, state);
1764	    if (early) {
1765	      early.actionAttempts = state.actionAttempts;
1766	      // A failed form (invalid_input) or failed condition evaluation
1767	      // (invalid_condition) ends normal execution and triggers compensation
1768	      // of the successful business actions that ran earlier.
1769	      return withCompensation(early, state, operations);
1770	    }
1771	  }
1772	}
