// and preserves the distinction between shared and distinct objects).
function expectedRestoredContent() {
  const root = {
    hub: { tag: 'kept', oneDefault: 'ONE' },
    linkA: undefined,
    linkB: undefined,
    ring: {},
    n: 'many',
  };
  root.linkA = root.hub;
  root.linkB = root.hub;
  root.ring.self = root;
  root.ring.peer = root.hub;
  return root;
}

